  const arr=Array.from({length:Math.max(4,k+1,s.handlePos?.length??0)},(_,i)=>s.handlePos?.[i]??null);arr[k]=pos;
  if(arr.some(x=>x!==null))s.handlePos=arr;else delete s.handlePos;
